const now = new Date();
const reportYear = now.getFullYear() - 1;

function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}

const fileName = `تقرير_سنوي_${reportYear}.docx`;
const yearsComparison = [reportYear, reportYear - 1, reportYear - 2, reportYear - 3, reportYear - 4];

return {
  json: {
    year: reportYear,
    year_arabic: toArabicNumerals(reportYear),
    file_name: fileName,
    report_title: `التقرير السنوي الشامل للرصد الجنائي - ${toArabicNumerals(reportYear)}`,
    years_comparison: yearsComparison,
    current_year: now.getFullYear()
  }
};

